const mongoose = require('mongoose');

/**
 * Customer model.
 * email and phone are enforced as unique at the DB index level.
 * customerCode auto-generated by the controller if not supplied.
 */
const customerSchema = new mongoose.Schema({
  customerCode: { type: String, required: true, unique: true, uppercase: true, trim: true, maxlength: 20 },
  customerName: { type: String, required: true, trim: true, maxlength: 150 },
  email:        { type: String, required: true, unique: true, lowercase: true, trim: true, maxlength: 200 },
  phone:        { type: String, required: true, unique: true, trim: true, maxlength: 20 },
  companyName:  { type: String, trim: true, maxlength: 200 },
  address:      { type: String, maxlength: 500 },
  city:         { type: String, maxlength: 100 },
  state:        { type: String, maxlength: 100 },
  status: {
    type: String,
    enum: ['Active', 'Inactive', 'Prospect', 'Churned'],
    default: 'Active'
  },
  owner: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
}, { timestamps: true });

// Text index for search
customerSchema.index({ customerName: 'text', email: 'text', companyName: 'text', phone: 'text' });

module.exports = mongoose.model('Customer', customerSchema);
